type Role = "PROPERTY_MANAGER" | "TENANT" | "TECHNICIAN" | "FLAT_OWNER";
type Status = "OPEN" | "ASSIGNED" | "IN_PROGRESS" | "RESOLVED" | "CLOSED";
type Ticket = { id: string; title: string; unit: string; category: string; priority: "LOW" | "MEDIUM" | "HIGH" | "EMERGENCY"; status: Status; age: string; assignee?: string; description: string };
type MediaContentType = "image/jpeg" | "image/png" | "image/webp" | "video/mp4" | "video/quicktime";
type MediaUploadInput = { ticketId: number; fileName: string; contentType: MediaContentType; base64Data: string };

async function uploadTenantFiles(files: File[], ticketId: number, upload: (input: MediaUploadInput) => Promise<unknown>, onProgress: (fileName: string, state: "uploading" | "success" | "failed") => void) {
  return Promise.allSettled(files.map(file => new Promise<void>((resolve, reject) => {
    onProgress(file.name, "uploading");
    const reader = new FileReader();
    reader.onload = async () => {
      try {
        await upload({ ticketId, fileName: file.name, contentType: file.type as MediaContentType, base64Data: String(reader.result) });
        onProgress(file.name, "success");
        resolve();
      } catch (error) {
        onProgress(file.name, "failed");
        reject(error);
      }
    };
    reader.onerror = () => { onProgress(file.name, "failed"); reject(new Error("Unable to read media file")); };
    reader.readAsDataURL(file);
  })));
}


