function AuthPage({ mode }: { mode: "sign-in" | "sign-up" }) { const { t } = useLanguage(); const [, navigate] = useLocation(); const [name, setName] = useState(""); const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const signIn = trpc.auth.signIn.useMutation(); const signUp = trpc.auth.signUp.useMutation(); const mutation = mode === "sign-in" ? signIn : signUp; const submit = async (event: React.FormEvent) => { event.preventDefault(); try { if (mode === "sign-in") { await signIn.mutateAsync({ email, password }); } else { await signUp.mutateAsync({ name, email, password }); } navigate("/"); window.location.reload(); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to authenticate", "تعذر تسجيل الدخول")); } }; return <div className="grid min-h-screen place-items-center bg-[#080b12] p-6 text-white"><Card className="w-full max-w-md rounded-3xl border-white/[.1] bg-[#101521] p-3"><CardHeader><Link href="/" className="mb-8 text-sm text-slate-500 hover:text-white">{t("← Back to Maintainr", "← العودة إلى Maintainr")}</Link><div className="grid size-12 place-items-center rounded-2xl bg-violet-400/10 text-violet-300"><ShieldCheck/></div><CardTitle className="mt-5 text-3xl">{mode === "sign-in" ? t("Sign in to your portal", "سجل الدخول إلى بوابتك") : t("Set up the Manager workspace", "إعداد مساحة عمل المدير")}</CardTitle><p className="text-slate-400">{mode === "sign-in" ? t("Tenants, technicians, owners, and managers use this same secure sign-in. Your role opens the correct portal automatically.", "يستخدم المستأجرون والفنيون والملاك والمديرون تسجيل الدخول الآمن نفسه. ستفتح بوابتك حسب دورك تلقائياً.") : t("Use this one-time setup only with the configured Manager email. Tenants and technicians should apply for access instead.", "استخدم هذا الإعداد مرة واحدة فقط مع بريد المدير المكوّن. يجب على المستأجرين والفنيين تقديم طلب وصول بدلاً من ذلك.")}</p></CardHeader><CardContent><form onSubmit={submit} className="space-y-4">{mode === "sign-up" && <Input required minLength={2} value={name} onChange={e => setName(e.target.value)} placeholder={t("Full name", "الاسم الكامل")} /> }<Input required type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder={t("Email address", "البريد الإلكتروني")} /><Input required minLength={8} type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder={t("Password (8+ characters)", "كلمة المرور (8 أحرف فأكثر)")} /><Button type="submit" disabled={mutation.isPending} className="h-12 w-full rounded-xl bg-violet-500 hover:bg-violet-400">{mutation.isPending ? t("Please wait...", "يرجى الانتظار...") : mode === "sign-in" ? t("Sign in", "تسجيل الدخول") : t("Create account", "إنشاء الحساب")}<ArrowRight size={16}/></Button></form><div className="mt-4 rounded-xl border border-white/[.07] bg-white/[.02] p-4 text-xs leading-5 text-slate-500">{t("Your password is hashed on the server and sessions are stored as revocable hashes in PostgreSQL. Your role and organization access are checked after authentication.", "يتم تشفير كلمة المرور على الخادم وتخزين الجلسات بشكل آمن في PostgreSQL. يتم التحقق من الدور وصلاحية المؤسسة بعد تسجيل الدخول.")}</div>{mode === "sign-in" && <Link href="/forgot-password" className="mt-4 block text-center text-sm text-slate-400 hover:text-violet-200">{t("Forgot password?", "هل نسيت كلمة المرور؟")}</Link>}{mode === "sign-in" ? <><Link href="/apply" className="mt-4 block text-center text-sm text-cyan-300 hover:text-cyan-200">{t("Tenant or technician? Apply for access", "مستأجر أو فني؟ اطلب الوصول")}</Link><Link href="/sign-up" className="mt-3 block text-center text-xs text-slate-500 hover:text-violet-200">{t("First-time Manager workspace setup", "إعداد مساحة المدير لأول مرة")}</Link></> : <Link href="/sign-in" className="mt-4 block text-center text-sm text-violet-300 hover:text-violet-200">{t("Already have an account? Sign in", "لديك حساب؟ سجل الدخول")}</Link>}</CardContent></Card></div>; }

function ForgotPasswordPage() { const { t } = useLanguage(); const [email, setEmail] = useState(""); const request = trpc.auth.requestPasswordReset.useMutation(); const submit = async (event: React.FormEvent) => { event.preventDefault(); try { await request.mutateAsync({ email }); toast.success(t("If that account exists, a reset email has been sent.", "إذا كان الحساب موجوداً، فسيتم إرسال رسالة إعادة التعيين.")); setEmail(""); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to request a reset", "تعذر طلب إعادة التعيين")); } }; return <div className="grid min-h-screen place-items-center bg-[#080b12] p-6 text-white"><Card className="w-full max-w-md rounded-3xl border-white/[.1] bg-[#101521] p-3"><CardHeader><Link href="/sign-in" className="mb-8 text-sm text-slate-500 hover:text-white">{t("← Back to sign in", "← العودة إلى تسجيل الدخول")}</Link><CardTitle className="text-3xl">{t("Reset your password", "إعادة تعيين كلمة المرور")}</CardTitle><p className="text-slate-400">{t("Enter your email and we will send a time-limited reset link.", "أدخل بريدك الإلكتروني وسنرسل رابط إعادة تعيين محدود الصلاحية.")}</p></CardHeader><CardContent><form onSubmit={submit} className="space-y-4"><Input required type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder={t("Email address", "البريد الإلكتروني")} /><Button type="submit" disabled={request.isPending} className="h-12 w-full bg-violet-500 hover:bg-violet-400">{request.isPending ? t("Sending...", "جارٍ الإرسال...") : t("Send reset link", "إرسال رابط التعيين")}</Button></form></CardContent></Card></div>; }

function ResetPasswordPage() { const { t } = useLanguage(); const [password, setPassword] = useState(""); const [confirm, setConfirm] = useState(""); const [token] = useState(() => typeof window === "undefined" ? "" : new URLSearchParams(window.location.search).get("token") || ""); const reset = trpc.auth.resetPassword.useMutation(); const submit = async (event: React.FormEvent) => { event.preventDefault(); if (password !== confirm) { toast.error(t("Passwords do not match", "كلمتا المرور غير متطابقتين")); return; } try { await reset.mutateAsync({ token, password }); toast.success(t("Password updated. You can sign in now.", "تم تحديث كلمة المرور. يمكنك تسجيل الدخول الآن.")); window.location.href = "/sign-in"; } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to reset password", "تعذر إعادة تعيين كلمة المرور")); } }; return <div className="grid min-h-screen place-items-center bg-[#080b12] p-6 text-white"><Card className="w-full max-w-md rounded-3xl border-white/[.1] bg-[#101521] p-3"><CardHeader><Link href="/sign-in" className="mb-8 text-sm text-slate-500 hover:text-white">{t("← Back to sign in", "← العودة إلى تسجيل الدخول")}</Link><CardTitle className="text-3xl">{t("Choose a new password", "اختر كلمة مرور جديدة")}</CardTitle></CardHeader><CardContent><form onSubmit={submit} className="space-y-4"><Input required minLength={8} type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder={t("New password (8+ characters)", "كلمة المرور الجديدة (8 أحرف فأكثر)")} /><Input required minLength={8} type="password" value={confirm} onChange={e => setConfirm(e.target.value)} placeholder={t("Confirm password", "تأكيد كلمة المرور")} /><Button type="submit" disabled={reset.isPending || !token} className="h-12 w-full bg-violet-500 hover:bg-violet-400">{reset.isPending ? t("Updating...", "جارٍ التحديث...") : t("Update password", "تحديث كلمة المرور")}</Button></form></CardContent></Card></div>; }

function JoinUnit() { const { t } = useLanguage(); const [code, setCode] = useState(""); const [, navigate] = useLocation(); const joinUnit = trpc.onboarding.joinUnit.useMutation(); const valid = /^\d{6}$/.test(code); return <div className="grid min-h-screen place-items-center bg-[#080b12] p-6 text-white"><Card className="w-full max-w-md rounded-3xl border-white/[.1] bg-[#101521] p-3"><CardHeader><Link href="/" className="mb-8 text-sm text-slate-500 hover:text-white">{t("← Back to Maintainr", "← العودة إلى Maintainr")}</Link><div className="grid size-12 place-items-center rounded-2xl bg-cyan-400/10 text-cyan-300"><HomeIcon/></div><CardTitle className="mt-5 text-3xl">{t("Join your unit", "انضم إلى وحدتك")}</CardTitle><p className="text-slate-400">{t("Enter the six-digit access code from your property manager.", "أدخل رمز الدخول المكون من ستة أرقام الذي أرسله مدير العقار.")}</p></CardHeader><CardContent className="space-y-5"><Input inputMode="numeric" maxLength={6} value={code} onChange={e => setCode(e.target.value.replace(/\D/g, ""))} placeholder="000000" className="h-14 border-white/10 bg-white/[.04] text-center text-2xl tracking-[.5em]"/><Button disabled={!valid} className="h-12 w-full rounded-xl bg-cyan-400 text-black hover:bg-cyan-300" onClick={async () => { try { await joinUnit.mutateAsync({ accessCode: code }); toast.success(t("Unit code verified", "تم التحقق من رمز الوحدة")); navigate("/tenant"); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to join this unit", "تعذر الانضمام إلى هذه الوحدة")); } }}>{joinUnit.isPending ? t("Joining...", "جارٍ الانضمام...") : t("Continue", "متابعة")} <ArrowRight size={16}/></Button><p className="text-center text-xs text-slate-500">{t("Code must be exactly 6 digits. Your manager can generate one from People.", "يجب أن يتكون الرمز من ستة أرقام بالضبط. يمكن لمدير العقار إنشاء الرمز من قسم الأشخاص.")}</p></CardContent></Card></div>; }

function Header({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) { const { t } = useLanguage(); const arabic: Record<string, string> = { "Manager command center": "لوحة تحكم المدير", "Good morning, Alex.": "صباح الخير، أليكس.", "Here’s what needs your attention across Westbridge Living today.": "إليك أهم المهام التي تحتاج إلى انتباهك اليوم في ويستبريدج ليفينغ.", "Resident portal": "بوابة المستأجر", "Your home, looked after.": "منزلك محل اهتمامنا.", "Stay close to every request and know exactly what happens next.": "تابع كل طلب واعرف ما سيحدث بعد ذلك.", "Field operations": "العمليات الميدانية", "Your route for today.": "مسارك لهذا اليوم.", "Three jobs are queued. Start with the emergency electrical call.": "لديك ثلاث مهام. ابدأ بالبلاغ الكهربائي الطارئ.", "Owner view": "واجهة المالك", "Confidence in every detail.": "ثقة في كل التفاصيل.", "A read-only view of maintenance performance across your portfolio.": "عرض شامل لأداء الصيانة في محفظتك.", "Flat Owner": "مالك الشقة", "Property Manager": "مدير العقار", "Tenant": "المستأجر", "Field Technician": "الفني الميداني" }; return <div className="mb-8 flex min-w-0 flex-col justify-between gap-5 overflow-hidden sm:flex-row sm:items-end"><div className="min-w-0"><div className="text-xs font-semibold uppercase tracking-[.25em] text-violet-400">{t(eyebrow, arabic[eyebrow] || eyebrow)}</div><h1 className="mt-2 text-3xl font-semibold tracking-[-.03em] text-white sm:text-4xl">{t(title, arabic[title] || title)}</h1><p className="mt-2 max-w-2xl text-sm text-slate-500">{t(description, arabic[description] || description)}</p></div>{action && <div className="flex max-w-full flex-wrap items-center gap-2 [&>button]:max-w-full">{action}</div>}</div>; }

function PeopleView() { const { t } = useLanguage(); const [tenantName, setTenantName] = useState(""); const [tenantEmail, setTenantEmail] = useState(""); const [unitId, setUnitId] = useState("1"); const [technicianName, setTechnicianName] = useState(""); const [technicianEmail, setTechnicianEmail] = useState(""); const [code, setCode] = useState<string | undefined>(); const createTenant = trpc.manager.createTenant.useMutation(); const inviteTechnician = trpc.manager.inviteTechnician.useMutation(); const generateUnitCode = trpc.manager.generateUnitCode.useMutation(); return <AppShell role="PROPERTY_MANAGER"><Header eyebrow="People" title={t("People and access", "الأشخاص والوصول")} description={t("Create tenant access, invite technicians, and generate unit codes from one simple workspace.", "أنشئ وصول المستأجرين وادعُ الفنيين وأنشئ رموز الوحدات من مساحة واحدة بسيطة.")} /><div className="grid gap-6 lg:grid-cols-3"><Card className="border-white/[.07] bg-[#101521]"><CardHeader><CardTitle>{t("Create tenant", "إنشاء مستأجر")}</CardTitle><p className="text-xs text-slate-500">{t("Create an account and connect it to a unit.", "أنشئ حساباً واربطه بوحدة.")}</p></CardHeader><CardContent className="space-y-3"><Input value={tenantName} onChange={e => setTenantName(e.target.value)} placeholder={t("Tenant name", "اسم المستأجر")} /><Input value={tenantEmail} onChange={e => setTenantEmail(e.target.value)} placeholder={t("Email address", "البريد الإلكتروني")} type="email" /><Input value={unitId} onChange={e => setUnitId(e.target.value)} placeholder={t("Unit ID", "رقم الوحدة")} inputMode="numeric" /><Button disabled={createTenant.isPending || !tenantName.trim() || !tenantEmail.trim() || !Number(unitId)} className="w-full bg-cyan-400 text-black" onClick={async () => { try { await createTenant.mutateAsync({ name: tenantName, email: tenantEmail, unitId: Number(unitId) }); toast.success(t("Tenant created", "تم إنشاء المستأجر")); setTenantName(""); setTenantEmail(""); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to create tenant", "تعذر إنشاء المستأجر")); } }}>{t("Create tenant", "إنشاء المستأجر")}</Button></CardContent></Card><Card className="border-white/[.07] bg-[#101521]"><CardHeader><CardTitle>{t("Invite technician", "دعوة فني")}</CardTitle><p className="text-xs text-slate-500">{t("Send a secure invitation for field operations.", "أرسل دعوة آمنة للعمليات الميدانية.")}</p></CardHeader><CardContent className="space-y-3"><Input value={technicianName} onChange={e => setTechnicianName(e.target.value)} placeholder={t("Technician name", "اسم الفني")} /><Input value={technicianEmail} onChange={e => setTechnicianEmail(e.target.value)} placeholder={t("Email address", "البريد الإلكتروني")} type="email" /><Button disabled={inviteTechnician.isPending || !technicianName.trim() || !technicianEmail.trim()} className="w-full bg-violet-500" onClick={async () => { try { await inviteTechnician.mutateAsync({ name: technicianName, email: technicianEmail }); toast.success(t("Invitation sent", "تم إرسال الدعوة")); setTechnicianName(""); setTechnicianEmail(""); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to send invitation", "تعذر إرسال الدعوة")); } }}>{t("Send invitation", "إرسال الدعوة")}</Button></CardContent></Card><Card className="border-white/[.07] bg-[#101521]"><CardHeader><CardTitle>{t("Unit access code", "رمز دخول الوحدة")}</CardTitle><p className="text-xs text-slate-500">{t("Generate a six-digit code for a tenant.", "أنشئ رمزاً من ستة أرقام للمستأجر.")}</p></CardHeader><CardContent className="space-y-3"><Input value={unitId} onChange={e => setUnitId(e.target.value)} placeholder={t("Unit ID", "رقم الوحدة")} inputMode="numeric" /><Button disabled={generateUnitCode.isPending || !Number(unitId)} className="w-full bg-emerald-500 text-black" onClick={async () => { try { const result = await generateUnitCode.mutateAsync({ unitId: Number(unitId) }); setCode(result.accessCode); toast.success(t("Code generated", "تم إنشاء الرمز")); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to generate code", "تعذر إنشاء الرمز")); } }}>{t("Generate code", "إنشاء الرمز")}</Button>{code && <div className="rounded-xl border border-emerald-400/30 bg-emerald-400/10 p-4 text-center text-2xl font-semibold tracking-[.35em] text-emerald-200">{code}</div>}</CardContent></Card></div></AppShell>; }

function ReminderView() { const { t } = useLanguage(); const reminders = trpc.reminders.list.useQuery(); const createReminder = trpc.reminders.create.useMutation(); const removeReminder = trpc.reminders.remove.useMutation(); const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); const [cadence, setCadence] = useState<"ONCE" | "DAILY" | "WEEKLY" | "MONTHLY" | "YEARLY">("MONTHLY"); const [dueAt, setDueAt] = useState(""); const submit = async () => { if (!title.trim() || !description.trim() || !dueAt) return; try { await createReminder.mutateAsync({ title, description, cadence, dueAt: new Date(dueAt).toISOString() }); await reminders.refetch(); setTitle(""); setDescription(""); setDueAt(""); toast.success(t("Reminder scheduled", "تمت جدولة التذكير")); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to schedule reminder", "تعذر جدولة التذكير")); } }; return <AppShell role="PROPERTY_MANAGER"><Header eyebrow={t("Maintenance reminders", "تذكيرات الصيانة")} title={t("Keep every recurring task visible.", "اجعل كل مهمة متكررة واضحة.")} description={t("Schedule inspections, filter changes, safety checks, and other property work from one place.", "جدول الفحوصات وتغيير الفلاتر وفحوصات السلامة وأعمال العقار من مكان واحد.")} /><div className="grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><Card className="border-white/[.07] bg-[#101521]"><CardHeader><CardTitle>{t("Create reminder", "إنشاء تذكير")}</CardTitle><p className="text-xs text-slate-500">{t("Recurring reminders run automatically after deployment.", "تعمل التذكيرات المتكررة تلقائياً بعد النشر.")}</p></CardHeader><CardContent className="space-y-3"><Input value={title} onChange={e => setTitle(e.target.value)} placeholder={t("Reminder title", "عنوان التذكير")} className="border-white/10 bg-white/[.03]"/><Textarea value={description} onChange={e => setDescription(e.target.value)} placeholder={t("What needs to happen?", "ما الذي يجب تنفيذه؟")} className="border-white/10 bg-white/[.03]"/><Select value={cadence} onValueChange={value => setCadence(value as typeof cadence)}><SelectTrigger className="border-white/10 bg-white/[.03]"><SelectValue placeholder={t("Cadence", "التكرار")}/></SelectTrigger><SelectContent>{(["ONCE","DAILY","WEEKLY","MONTHLY","YEARLY"] as const).map(value => <SelectItem key={value} value={value}>{maintenanceLabel(value, t)}</SelectItem>)}</SelectContent></Select><Input type="datetime-local" value={dueAt} onChange={e => setDueAt(e.target.value)} className="border-white/10 bg-white/[.03]"/><Button onClick={submit} disabled={createReminder.isPending || !title.trim() || !description.trim() || !dueAt} className="w-full bg-cyan-400 text-black hover:bg-cyan-300">{createReminder.isPending ? t("Scheduling...", "جارٍ الجدولة...") : t("Schedule reminder", "جدولة التذكير")}</Button></CardContent></Card><Card className="border-white/[.07] bg-[#101521]"><CardHeader><CardTitle>{t("Scheduled reminders", "التذكيرات المجدولة")}</CardTitle></CardHeader><CardContent className="space-y-3">{reminders.isLoading ? <div className="text-sm text-slate-500">{t("Loading reminders...", "جارٍ تحميل التذكيرات...")}</div> : reminders.data?.length ? reminders.data.map(reminder => <div key={reminder.id} className="flex items-start justify-between gap-4 rounded-2xl border border-white/[.07] bg-white/[.025] p-4"><div><div className="font-medium">{reminder.title}</div><div className="mt-1 text-xs text-slate-500">{reminder.description}</div><div className="mt-2 text-xs text-cyan-300">{maintenanceLabel(reminder.cadence, t)} · {new Date(reminder.nextRunAt).toLocaleString()}</div></div><Button size="sm" variant="outline" className="border-rose-400/30 bg-transparent text-rose-200" onClick={async () => { await removeReminder.mutateAsync({ id: reminder.id }); await reminders.refetch(); }}>{t("Remove", "إزالة")}</Button></div>) : <div className="rounded-2xl border border-dashed border-white/10 p-8 text-center text-sm text-slate-500">{t("No reminders scheduled yet.", "لا توجد تذكيرات مجدولة بعد.")}</div>}</CardContent></Card></div></AppShell>; }

function DeveloperSettingsView() { const { t } = useLanguage(); const settings = trpc.settings.get.useQuery(); const update = trpc.settings.update.useMutation(); const [form, setForm] = useState({ projectName: "Maintainr", projectNameArabic: "Maintainr", logoUrl: "", primaryColor: "#8B5CF6", accentColor: "#22D3EE", emailNotificationsEnabled: false, smsNotificationsEnabled: false }); useEffect(() => { if (settings.data) setForm({ projectName: settings.data.projectName, projectNameArabic: settings.data.projectNameArabic, logoUrl: settings.data.logoUrl ?? "", primaryColor: settings.data.primaryColor, accentColor: settings.data.accentColor, emailNotificationsEnabled: settings.data.emailNotificationsEnabled, smsNotificationsEnabled: settings.data.smsNotificationsEnabled }); }, [settings.data]); const save = async () => { try { await update.mutateAsync(form); await settings.refetch(); toast.success(t("Developer settings saved", "تم حفظ إعدادات المطور")); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to save settings", "تعذر حفظ الإعدادات")); } }; return <AppShell role="PROPERTY_MANAGER"><Header eyebrow={t("Developer settings", "إعدادات المطور")} title={t("Make Maintainr yours.", "اجعل Maintainr خاصاً بك.")} description={t("Configure branding and notification channels for your organization. Provider secrets stay in environment settings, never in the public UI.", "اضبط الهوية وقنوات الإشعارات لمؤسستك. تبقى مفاتيح المزود في إعدادات البيئة ولا تظهر في الواجهة العامة.")} /><Card className="max-w-3xl border-white/[.07] bg-[#101521]"><CardContent className="grid gap-4 p-6 sm:grid-cols-2"><Input value={form.projectName} onChange={e => setForm({ ...form, projectName: e.target.value })} placeholder={t("Project name", "اسم المشروع")} className="border-white/10 bg-white/[.03]"/><Input value={form.projectNameArabic} onChange={e => setForm({ ...form, projectNameArabic: e.target.value })} placeholder={t("Project name in Arabic", "اسم المشروع بالعربية")} dir="rtl" className="border-white/10 bg-white/[.03]"/><Input value={form.logoUrl} onChange={e => setForm({ ...form, logoUrl: e.target.value })} placeholder={t("Logo URL", "رابط الشعار")} className="border-white/10 bg-white/[.03]"/><label className="text-sm text-slate-400">{t("Primary color", "اللون الأساسي")}<Input type="color" value={form.primaryColor} onChange={e => setForm({ ...form, primaryColor: e.target.value })} className="mt-2 h-12 border-white/10 bg-white/[.03]"/></label><label className="text-sm text-slate-400">{t("Accent color", "اللون المميز")}<Input type="color" value={form.accentColor} onChange={e => setForm({ ...form, accentColor: e.target.value })} className="mt-2 h-12 border-white/10 bg-white/[.03]"/></label><label className="col-span-full flex items-center gap-3 rounded-xl border border-white/10 p-4 text-sm"><input type="checkbox" checked={form.emailNotificationsEnabled} onChange={e => setForm({ ...form, emailNotificationsEnabled: e.target.checked })}/>{t("Enable email notifications", "تفعيل إشعارات البريد الإلكتروني")}</label><label className="col-span-full flex items-center gap-3 rounded-xl border border-white/10 p-4 text-sm"><input type="checkbox" checked={form.smsNotificationsEnabled} onChange={e => setForm({ ...form, smsNotificationsEnabled: e.target.checked })}/>{t("Enable SMS notifications", "تفعيل إشعارات الرسائل النصية")}</label><div className="col-span-full rounded-xl bg-amber-400/10 p-4 text-xs leading-5 text-amber-100">{t("Add RESEND_API_KEY and NOTIFICATION_FROM_EMAIL for email. Add TWILIO_ENABLED=true, TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, and TWILIO_FROM for SMS.", "أضف RESEND_API_KEY وNOTIFICATION_FROM_EMAIL للبريد. أضف TWILIO_ENABLED=true وTWILIO_ACCOUNT_SID وTWILIO_AUTH_TOKEN وTWILIO_FROM للرسائل النصية.")}</div><Button onClick={save} disabled={update.isPending} className="col-span-full bg-violet-500 hover:bg-violet-400">{update.isPending ? t("Saving...", "جارٍ الحفظ...") : t("Save developer settings", "حفظ إعدادات المطور")}</Button></CardContent></Card></AppShell>; }

function ManagerTicketActions({ ticketId, priority, technicians, isLoading, isError }: { ticketId: string; priority: "LOW" | "MEDIUM" | "HIGH" | "EMERGENCY"; technicians: Array<{ id: number; name: string | null; email: string | null }>; isLoading: boolean; isError: boolean }) { const { t } = useLanguage(); const [selectedTechnicianId, setSelectedTechnicianId] = useState("none"); const assignTicket = trpc.tickets.assign.useMutation(); const setPriority = trpc.tickets.setPriority.useMutation(); const utils = trpc.useUtils(); const numericId = ticketId.startsWith("MT-") ? Number(ticketId.replace("MT-", "")) : 0; return <div className="mt-3 flex flex-wrap items-center gap-2" onClick={event => event.stopPropagation()}>{isLoading ? <span className="text-[11px] text-slate-500">{t("Loading technicians...", "جارٍ تحميل الفنيين...")}</span> : isError ? <span className="text-[11px] text-rose-300">{t("Technicians unavailable", "الفنيون غير متاحين")}</span> : technicians.length === 0 ? <span className="text-[11px] text-slate-500">{t("No technicians yet", "لا يوجد فنيون بعد")}</span> : <><Select value={selectedTechnicianId} onValueChange={setSelectedTechnicianId}><SelectTrigger className="h-8 w-36 border-white/10 bg-transparent text-[11px]"><SelectValue placeholder={t("Choose technician", "اختر الفني")} /></SelectTrigger><SelectContent><SelectItem value="none">{t("Choose technician", "اختر الفني")}</SelectItem>{technicians.map(technician => <SelectItem key={technician.id} value={String(technician.id)}>{technician.name ?? technician.email ?? `#${technician.id}`}</SelectItem>)}</SelectContent></Select><Button size="sm" variant="outline" disabled={selectedTechnicianId === "none" || assignTicket.isPending || !numericId} className="border-white/10 bg-transparent text-xs" onClick={async () => { if (selectedTechnicianId === "none" || !numericId) return; try { await assignTicket.mutateAsync({ ticketId: numericId, technicianId: Number(selectedTechnicianId) }); await utils.tickets.list.invalidate(); toast.success(t("Technician assigned", "تم تعيين الفني")); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to assign technician", "تعذر تعيين الفني")); } }}>{assignTicket.isPending ? t("Assigning...", "جارٍ التعيين...") : t("Assign", "تعيين")}</Button></>}<Button size="sm" variant="outline" disabled={setPriority.isPending || !numericId} className="border-white/10 bg-transparent text-xs" onClick={async () => { const choices = ["LOW", "MEDIUM", "HIGH", "EMERGENCY"] as const; const next = choices[(choices.indexOf(priority) + 1) % choices.length]; try { await setPriority.mutateAsync({ ticketId: numericId, priority: next }); await utils.tickets.list.invalidate(); toast.success(t(`Priority: ${next}`, `الأولوية: ${next}`)); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to update priority", "تعذر تحديث الأولوية")); } }}>{setPriority.isPending ? t("Saving...", "جارٍ الحفظ...") : t("Priority", "الأولوية")}</Button></div>; }

function ManagerPortal() { const { t } = useLanguage(); const translate = t; const updateStatus = trpc.tickets.updateStatus.useMutation(); const assignTicket = trpc.tickets.assign.useMutation(); const setPriority = trpc.tickets.setPriority.useMutation(); const utils = trpc.useUtils(); const technicians = trpc.manager.listTechnicians.useQuery(undefined, { retry: false }); const [selectedTechnicianId, setSelectedTechnicianId] = useState(""); const liveTickets = trpc.tickets.list.useQuery(undefined, { retry: false }); const [tickets, setTickets] = useState<Ticket[]>([]); useEffect(() => { if (liveTickets.data) setTickets(liveTickets.data.map(ticket => ({ id: `MT-${ticket.id}`, title: ticket.title, unit: `Unit ${ticket.unitId}`, category: ticket.category, priority: ticket.priority, status: ticket.status, age: new Date(ticket.createdAt).toLocaleDateString(), description: ticket.description }))); }, [liveTickets.data]); const [view, setView] = useState<"kanban" | "list">("kanban"); const [filter, setFilter] = useState("ALL"); const [priorityFilter, setPriorityFilter] = useState("ALL"); const [categoryFilter, setCategoryFilter] = useState("ALL"); const filtered = tickets.filter(t => (filter === "ALL" || t.status === filter) && (priorityFilter === "ALL" || t.priority === priorityFilter) && (categoryFilter === "ALL" || t.category === categoryFilter)); const statuses: Status[] = ["OPEN", "ASSIGNED", "IN_PROGRESS", "RESOLVED"]; if (typeof window !== "undefined" && new URLSearchParams(window.location.search).get("view") === "people") return <PeopleView />; if (typeof window !== "undefined" && new URLSearchParams(window.location.search).get("view") === "reminders") return <ReminderView />; if (typeof window !== "undefined" && new URLSearchParams(window.location.search).get("view") === "settings") return <DeveloperSettingsView />; return <AppShell role="PROPERTY_MANAGER"><ManagerApplicationsPanel/><ManagerAccessTools/><Header eyebrow={t("Manager command center", "مركز قيادة المدير")} title={t("Good morning, Alex.", "صباح الخير، أليكس.")} description={t("Here’s what needs your attention across Westbridge Living today.", "إليك ما يحتاج إلى انتباهك اليوم في ويستبريدج ليفينغ.")} action={<div className="flex gap-2"><Button variant="outline" className="border-white/10 bg-transparent" onClick={() => setView(view === "kanban" ? "list" : "kanban")}><LayoutDashboard size={16}/>{view === "kanban" ? t("List view", "عرض القائمة") : t("Kanban view", "عرض كانبان")}</Button><Button className="bg-violet-500 hover:bg-violet-400" onClick={() => document.getElementById("ticket-operations")?.scrollIntoView({ behavior: "smooth" })}><ClipboardList size={16}/>{t("View tickets", "عرض البلاغات")}</Button></div>}/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{([{ label: t("Open tickets", "البلاغات المفتوحة"), value: "12", sub: t("+3 this week", "+3 هذا الأسبوع"), icon: ClipboardList, color: "text-rose-300" }, { label: t("In progress", "قيد التنفيذ"), value: "07", sub: t("2 due today", "2 مستحقة اليوم"), icon: Clock3, color: "text-amber-300" }, { label: t("Resolved this month", "تم حلها هذا الشهر"), value: "34", sub: t("+18.2%", "+18.2%"), icon: CheckCircle2, color: "text-emerald-300" }, { label: t("Active technicians", "الفنيون النشطون"), value: "08", sub: t("All available", "الجميع متاح"), icon: Users, color: "text-cyan-300" }] as const).map(stat => { const StatIcon = stat.icon; return <Card key={stat.label} className="border-white/[.07] bg-[#101521]"><CardContent className="flex items-center justify-between p-5"><div><div className="text-xs text-slate-500">{stat.label}</div><div className="mt-2 text-3xl font-semibold">{stat.value}</div><div className="mt-1 text-xs text-slate-500">{stat.sub}</div></div><StatIcon className={stat.color} size={22}/></CardContent></Card>; })}</div><Card id="ticket-operations" className="mt-8 border-white/[.07] bg-[#101521]"><CardHeader className="flex flex-col gap-4 border-b border-white/[.07] pb-4 sm:flex-row sm:items-center sm:justify-between"><div><CardTitle className="text-lg">{t("Ticket operations", "عمليات البلاغات")}</CardTitle><p className="mt-1 text-xs text-slate-500">{t("Track every maintenance request from report to resolution.", "تابع كل طلب صيانة من البلاغ حتى الحل.")}</p></div><div className="flex w-full flex-wrap gap-2 sm:w-auto"><Select value={filter} onValueChange={setFilter}><SelectTrigger className="w-36 border-white/10 bg-white/[.03] text-xs"><Filter size={14}/><SelectValue placeholder={t("Filter status", "تصفية حسب الحالة")}/></SelectTrigger><SelectContent><SelectItem value="ALL">{t("All statuses", "كل الحالات")}</SelectItem>{statuses.map(s => <SelectItem key={s} value={s}>{maintenanceLabel(s, t)}</SelectItem>)}</SelectContent></Select><Select value={priorityFilter} onValueChange={setPriorityFilter}><SelectTrigger className="w-32 border-white/10 bg-white/[.03] text-xs"><SelectValue placeholder={t("Priority", "الأولوية")}/></SelectTrigger><SelectContent><SelectItem value="ALL">{t("All priorities", "كل الأولويات")}</SelectItem>{["LOW","MEDIUM","HIGH","EMERGENCY"].map(s => <SelectItem key={s} value={s}>{maintenanceLabel(s, t)}</SelectItem>)}</SelectContent></Select><Select value={categoryFilter} onValueChange={setCategoryFilter}><SelectTrigger className="w-32 border-white/10 bg-white/[.03] text-xs"><SelectValue placeholder={t("Category", "الفئة")}/></SelectTrigger><SelectContent><SelectItem value="ALL">{t("All categories", "كل الفئات")}</SelectItem>{["PLUMBING","ELECTRICAL","HVAC","APPLIANCE","OTHER"].map(s => <SelectItem key={s} value={s}>{maintenanceLabel(s, t)}</SelectItem>)}</SelectContent></Select></div></CardHeader><CardContent className="p-5">{view === "kanban" ? <div className="grid gap-4 xl:grid-cols-4">{statuses.map(status => <div key={status} className="min-w-0"><div className="mb-3 flex items-center justify-between"><div className="flex items-center gap-2 text-xs font-semibold text-slate-300"><span className={`size-2 rounded-full ${status === "OPEN" ? "bg-rose-400" : status === "ASSIGNED" ? "bg-violet-400" : status === "IN_PROGRESS" ? "bg-amber-400" : "bg-emerald-400"}`}/>{maintenanceLabel(status, t)}</div><span className="text-xs text-slate-600">{filtered.filter(t => t.status === status).length}</span></div><div className="space-y-3">{filtered.filter(t => t.status === status).map(t => <motion.div layout key={t.id} className="cursor-pointer rounded-2xl border border-white/[.07] bg-white/[.025] p-4 transition hover:border-violet-400/40" onClick={async () => { if (t.status !== "RESOLVED") { const nextStatus = status === "OPEN" ? "ASSIGNED" : status === "ASSIGNED" ? "IN_PROGRESS" : "RESOLVED"; setTickets(tickets.map(item => item.id === t.id ? {...item, status: nextStatus} : item)); try { if (t.id.startsWith("MT-")) { await updateStatus.mutateAsync({ ticketId: ticketIdFromUiId(t.id), status: nextStatus }); await utils.tickets.list.invalidate(); } toast.success(translate("Ticket updated and audit log recorded", "تم تحديث البلاغ وتسجيله في سجل التدقيق")); } catch (error) { toast.error(error instanceof Error ? error.message : translate("Unable to update ticket", "تعذر تحديث البلاغ")); } } }}><div className="flex items-start justify-between gap-2"><span className="text-[11px] text-slate-500">{t.id}</span><PriorityBadge priority={t.priority}/></div><div className="mt-2 text-sm font-medium leading-5">{t.title}</div><div className="mt-3 flex items-center justify-between text-xs text-slate-500"><span>{t.unit} · {t.category}</span><span>{t.age}</span></div>{t.assignee && <div className="mt-3 flex items-center gap-2 border-t border-white/[.06] pt-3 text-xs text-slate-400"><div className="grid size-5 place-items-center rounded-full bg-violet-400/20 text-[9px] text-violet-200">{t.assignee.split(" ").map(n => n[0]).join("")}</div>{t.assignee}</div>}<ManagerTicketActions ticketId={t.id} priority={t.priority} technicians={technicians.data ?? []} isLoading={technicians.isLoading} isError={technicians.isError}/></motion.div>)}</div></div>)}</div> : <div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="text-xs uppercase tracking-wider text-slate-600"><tr><th className="pb-4">{t("Ticket", "البلاغ")}</th><th className="pb-4">{t("Unit", "الوحدة")}</th><th className="pb-4">{t("Priority", "الأولوية")}</th><th className="pb-4">{t("Status", "الحالة")}</th><th className="pb-4">{t("Assignee", "المسند إليه")}</th><th className="pb-4">{t("Actions", "الإجراءات")}</th></tr></thead><tbody>{filtered.map(t => <tr key={t.id} className="border-t border-white/[.06]"><td className="py-4 font-medium">{t.title}<div className="text-xs text-slate-600">{t.id}</div></td><td className="py-4 text-slate-400">{t.unit}</td><td className="py-4"><PriorityBadge priority={t.priority}/></td><td className="py-4"><StatusBadge status={t.status}/></td><td className="py-4 text-slate-400">{t.assignee || "Unassigned"}</td><td className="py-4"><ManagerTicketActions ticketId={t.id} priority={t.priority} technicians={technicians.data ?? []} isLoading={technicians.isLoading} isError={technicians.isError}/></td></tr>)}</tbody></table></div>}</CardContent></Card></AppShell>; }

function TenantPortal() { const { t } = useLanguage(); const { user } = useAuth(); const createTicket = trpc.tickets.create.useMutation(); const attachMedia = trpc.tickets.attachMedia.useMutation(); const liveTickets = trpc.tickets.list.useQuery(undefined, { retry: false }); const utils = trpc.useUtils(); const ticketSource = liveTickets.data?.map(ticket => ({ id: `MT-${ticket.id}`, title: ticket.title, unit: `Unit ${ticket.unitId}`, category: ticket.category, priority: ticket.priority, status: ticket.status, age: new Date(ticket.createdAt).toLocaleDateString(), description: ticket.description })) ?? []; const [submitted, setSubmitted] = useState(false); const [createdTicketId, setCreatedTicketId] = useState<number | undefined>(); const [pendingFiles, setPendingFiles] = useState<File[]>([]); const [mediaStatus, setMediaStatus] = useState<"idle" | "uploading" | "complete" | "partial">("idle"); const [mediaErrors, setMediaErrors] = useState<string[]>([]); const [failedFiles, setFailedFiles] = useState<File[]>([]); const [mediaProgress, setMediaProgress] = useState<Record<string, "uploading" | "success" | "failed">>({}); const [historyQuery, setHistoryQuery] = useState(""); const [title, setTitle] = useState(""); const [category, setCategory] = useState<"PLUMBING" | "ELECTRICAL" | "HVAC" | "APPLIANCE" | "OTHER">("OTHER"); const [description, setDescription] = useState(""); const [preferredAccessTime, setPreferredAccessTime] = useState(""); const activeTicket = ticketSource.find(t => ["OPEN", "ASSIGNED", "IN_PROGRESS"].includes(t.status)); const history = ticketSource.filter(t => t.status === "RESOLVED" && `${t.title} ${t.id} ${t.category}`.toLowerCase().includes(historyQuery.toLowerCase())); const retryFailedMedia = async () => { if (!createdTicketId || !failedFiles.length) return; setMediaStatus("uploading"); const results = await uploadTenantFiles(failedFiles, createdTicketId, input => attachMedia.mutateAsync(input), (fileName, state) => setMediaProgress(previous => nextMediaState(previous, fileName, state))); const failed = failedUploadNames(failedFiles.map(file => file.name), results); setMediaErrors(failed); setFailedFiles(failedFiles.filter(file => retainedFailedFileNames(failedFiles.map(item => item.name), results).includes(file.name))); setMediaStatus(failed.length ? "partial" : "complete"); if (!failed.length) toast.success(t("All attachments uploaded", "تم رفع جميع المرفقات")); }; return <AppShell role="TENANT"><Header eyebrow="Resident portal" title="Your home, looked after." description="Stay close to every request and know exactly what happens next." action={<Button className="bg-cyan-400 text-black hover:bg-cyan-300" onClick={() => document.getElementById("submit-ticket")?.scrollIntoView({ behavior: "smooth" })}><Plus size={16}/>{t("Report an issue", "إبلاغ عن مشكلة")}</Button>}/><Card className="overflow-hidden border-cyan-400/20 bg-gradient-to-br from-cyan-400/[.12] to-[#101521]"><CardContent className="p-6 sm:p-8"><div className="flex flex-col justify-between gap-8 sm:flex-row"><div><div className="text-xs uppercase tracking-[.22em] text-cyan-300">{t("Active request", "البلاغ النشط")} · {activeTicket?.id ?? "—"}</div><h2 className="mt-3 text-2xl font-semibold">{activeTicket?.title ?? t("No active request", "لا يوجد بلاغ نشط")}</h2><p className="mt-2 text-sm text-slate-400">{activeTicket ? `${activeTicket.age} · ${activeTicket.unit}` : t("Submit a request to see updates here.", "أرسل بلاغاً لرؤية التحديثات هنا.")}</p></div><StatusBadge status={activeTicket?.status ?? "OPEN"}/></div><div className="mt-10 grid grid-cols-4 gap-2">{["OPEN", "ASSIGNED", "IN_PROGRESS", "RESOLVED"].map((step, index) => <div key={step}><div className={`h-1.5 rounded-full ${index < 3 ? "bg-cyan-400" : "bg-white/10"}`}/><div className={`mt-2 text-[10px] uppercase tracking-wider ${index < 3 ? "text-cyan-200" : "text-slate-600"}`}>{maintenanceLabel(step, t)}</div></div>)}</div><div className="mt-6 flex items-center gap-3 text-sm text-slate-400"><Clock3 size={16} className="text-cyan-300"/>{t("Your technician is expected today between 2:00–4:00 PM.", "من المتوقع وصول الفني اليوم بين الساعة 2:00 و4:00 مساءً.")}</div></CardContent></Card><div className="mt-8 grid gap-8 lg:grid-cols-[1.1fr_.9fr]"><Card id="submit-ticket" className="border-white/[.07] bg-[#101521]"><CardHeader><CardTitle className="text-lg">{t("Report a maintenance issue", "إبلاغ عن مشكلة صيانة")}</CardTitle><p className="text-xs text-slate-500">{t("Give your property team enough context to resolve it quickly.", "أضف التفاصيل التي تساعد فريق العقار على حل المشكلة بسرعة.")}</p></CardHeader><CardContent className="space-y-4"><Input value={title} onChange={e => setTitle(e.target.value)} placeholder={t("Short title, e.g. Bathroom tap is leaking", "عنوان مختصر، مثال: صنبور الحمام يتسرب") } className="border-white/10 bg-white/[.03]"/><Select value={category} onValueChange={value => setCategory(value as typeof category)}><SelectTrigger className="border-white/10 bg-white/[.03]"><SelectValue placeholder={t("Select category", "اختر الفئة")}/></SelectTrigger><SelectContent>{["PLUMBING","ELECTRICAL","HVAC","APPLIANCE","OTHER"].map(x => <SelectItem key={x} value={x}>{maintenanceLabel(x, t)}</SelectItem>)}</SelectContent></Select><Textarea value={description} onChange={e => setDescription(e.target.value)} placeholder={t("Describe what is happening...", "اشرح ما يحدث...")} className="min-h-28 border-white/10 bg-white/[.03]"/><div className="grid gap-4 sm:grid-cols-2"><Input value={preferredAccessTime} onChange={e => setPreferredAccessTime(e.target.value)} placeholder={t("Preferred access time", "وقت الدخول المفضل")} className="border-white/10 bg-white/[.03]"/><label className="flex cursor-pointer items-center justify-center gap-2 rounded-xl border border-dashed border-white/15 bg-white/[.02] text-sm text-slate-400 hover:border-cyan-400/40"><ImagePlus size={17}/>{pendingFiles.length ? `${pendingFiles.length} ${t("file(s) selected", "ملفات محددة")}` : t("Add photo/video", "إضافة صورة أو فيديو")}<input type="file" className="hidden" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime" multiple onChange={e => setPendingFiles(Array.from(e.target.files ?? []))}/></label></div><Button className="w-full bg-cyan-400 text-black hover:bg-cyan-300" onClick={async () => { if (!user?.unitId || title.trim().length < 3 || description.trim().length < 10) { toast.error(t("Add a title and at least 10 characters of detail.", "أضف عنواناً ووصفاً من 10 أحرف على الأقل.")); return; } try { setSubmitted(false); setMediaStatus("idle"); setMediaErrors([]); setFailedFiles([]); setMediaProgress({}); const created = await createTicket.mutateAsync({ unitId: user.unitId, title, description, category, priority: "MEDIUM", preferredAccessTime }); setCreatedTicketId(created.ticketId); if (pendingFiles.length) { setMediaStatus("uploading"); const results = await uploadTenantFiles(pendingFiles, created.ticketId, input => attachMedia.mutateAsync(input), (fileName, state) => setMediaProgress(previous => nextMediaState(previous, fileName, state))); const failed = failedUploadNames(pendingFiles.map(file => file.name), results); setMediaErrors(failed); setFailedFiles(pendingFiles.filter(file => retainedFailedFileNames(pendingFiles.map(item => item.name), results).includes(file.name))); setMediaStatus(failed.length ? "partial" : "complete"); if (failed.length) toast.warning(t(`${failed.length} file(s) need retry.`, `يحتاج ${failed.length} ملف إلى إعادة المحاولة.`)); } setPendingFiles([]); await utils.tickets.list.invalidate(); setSubmitted(true); setTitle(""); setDescription(""); toast.success(t("Ticket submitted. Your property team has been notified.", "تم إرسال البلاغ وإخطار فريق العقار.")); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to submit ticket", "تعذر إرسال البلاغ")); } }}>{createTicket.isPending ? t("Submitting...", "جارٍ الإرسال...") : mediaStatus === "uploading" ? t("Uploading media...", "جارٍ رفع الوسائط...") : t("Submit maintenance request", "إرسال طلب الصيانة")} <ArrowRight size={16}/></Button>{submitted && mediaStatus === "partial" && <div className="rounded-xl bg-amber-400/10 p-3 text-sm text-amber-200"><div>{t("Ticket created, but some files need retry: ", "تم إنشاء البلاغ، لكن بعض الملفات تحتاج إلى إعادة المحاولة: ")}{mediaErrors.join(", ")}</div><Button size="sm" variant="outline" className="mt-3 border-amber-300/30 bg-transparent text-amber-100" onClick={retryFailedMedia} disabled={false}>{t("Retry failed files", "إعادة رفع الملفات الفاشلة")}</Button></div>}{Object.entries(mediaProgress).length > 0 && <div className="space-y-1 text-xs text-slate-500">{Object.entries(mediaProgress).map(([fileName, state]) => <div key={fileName} className="flex items-center justify-between"><span className="truncate pr-3">{fileName}</span><span className={state === "failed" ? "text-rose-300" : state === "success" ? "text-emerald-300" : "text-cyan-300"}>{state === "uploading" ? t("Uploading", "جارٍ الرفع") : state === "success" ? t("Uploaded", "تم الرفع") : t("Failed", "فشل")}</span></div>)}</div>}{submitted && <div className="rounded-xl bg-emerald-400/10 p-3 text-sm text-emerald-300">{t("Request received. You’ll get updates here and by email.", "تم استلام الطلب. ستصلك التحديثات هنا وعبر البريد الإلكتروني.")}</div>}</CardContent></Card><Card className="border-white/[.07] bg-[#101521]"><CardHeader><CardTitle className="text-lg">{t("Maintenance history", "سجل الصيانة")}</CardTitle><div className="relative mt-3"><Search className="absolute left-3 top-2.5 text-slate-600" size={15}/><Input value={historyQuery} onChange={e => setHistoryQuery(e.target.value)} placeholder={t("Search repairs...", "البحث في الإصلاحات...")} className="border-white/10 bg-white/[.03] pl-9"/></div></CardHeader><CardContent className="space-y-1">{history.map(t => <div key={t.id} className="flex items-center justify-between border-b border-white/[.06] py-4"><div><div className="text-sm">{t.title}</div><div className="mt-1 text-xs text-slate-500">{t.id} · {t.age}</div></div><CheckCircle2 size={17} className="text-emerald-300"/></div>)}</CardContent></Card></div></AppShell>; }

function TechnicianPortal() { const { t } = useLanguage(); const attachMedia = trpc.tickets.attachMedia.useMutation(); const updateStatus = trpc.tickets.updateStatus.useMutation(); const completeTicket = trpc.technician.complete.useMutation(); const liveTickets = trpc.tickets.list.useQuery(undefined, { retry: false }); const utils = trpc.useUtils(); const jobSource = liveTickets.data?.map(ticket => ({ id: `MT-${ticket.id}`, title: ticket.title, unit: `Unit ${ticket.unitId}`, category: ticket.category, priority: ticket.priority, status: ticket.status, age: new Date(ticket.createdAt).toLocaleDateString(), description: ticket.description, assignee: "Assigned technician" })) ?? []; const [selectedTicketId, setSelectedTicketId] = useState(() => Number(jobSource[0]?.id.replace("MT-", "") ?? 0)); const selectedJob = jobSource.find(job => ticketIdFromUiId(job.id) === selectedTicketId) ?? jobSource[0]; const [status, setStatus] = useState<Status>(selectedJob?.status ?? "ASSIGNED"); useEffect(() => { if (selectedJob?.status) setStatus(selectedJob.status); }, [selectedJob?.id, selectedJob?.status]); const [notes, setNotes] = useState(""); const [proofUrl, setProofUrl] = useState(""); const canResolve = notes.trim().length > 5 && proofUrl.length > 0; return <AppShell role="TECHNICIAN"><Header eyebrow="Field operations" title="Your route for today." description={selectedJob ? `${jobSource.length} ${t("assigned jobs available", "مهام مسندة متاحة")} · ${selectedJob.category}` : t("Select an assigned job to begin.", "اختر مهمة مسندة للبدء.")} action={<div className="rounded-xl border border-amber-400/20 bg-amber-400/10 px-3 py-2 text-xs text-amber-200">{new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })} · {t("Today", "اليوم")}</div>}/><div className="grid gap-8 xl:grid-cols-[.9fr_1.1fr]"><Card className="border-white/[.07] bg-[#101521]"><CardHeader><div className="flex items-center justify-between"><CardTitle className="text-lg">{t("Assigned jobs", "المهام المسندة")}</CardTitle><Badge variant="outline" className="border-white/10 text-slate-400">3 jobs</Badge></div></CardHeader><CardContent className="space-y-3">{jobSource.filter(t => t.assignee).sort((a,b) => a.priority === "EMERGENCY" ? -1 : b.priority === "EMERGENCY" ? 1 : 0).map((t, i) => <div key={t.id} onClick={() => setSelectedTicketId(ticketIdFromUiId(t.id))} className={`cursor-pointer rounded-2xl border p-4 ${i === 0 ? "border-amber-400/30 bg-amber-400/[.06]" : "border-white/[.07] bg-white/[.025]"}`}><div className="flex justify-between"><span className="text-[11px] text-slate-500">{t.id} · {t.unit}</span><PriorityBadge priority={t.priority}/></div><div className="mt-2 font-medium">{t.title}</div><div className="mt-3 flex items-center justify-between"><StatusBadge status={t.status}/><span className="text-xs text-slate-500">{t.category}</span></div></div>)}</CardContent></Card><Card className="border-amber-400/20 bg-[#101521]"><CardHeader><div className="flex items-center justify-between"><div><div className="text-xs uppercase tracking-[.2em] text-amber-300">{t("Current job", "المهمة الحالية")} · MT-{selectedTicketId}</div><CardTitle className="mt-2 text-xl">{selectedJob?.title ?? t("Select a job", "اختر مهمة") }</CardTitle></div><PriorityBadge priority={selectedJob?.priority ?? "MEDIUM"}/></div><p className="text-sm text-slate-400">{selectedJob?.unit ?? t("Selected unit", "الوحدة المحددة")} · {selectedJob?.category ?? ""} · {t("Tenant access confirmed", "تم تأكيد دخول المستأجر")}</p></CardHeader><CardContent className="space-y-5"><div className="grid gap-3 rounded-2xl border border-white/[.07] bg-white/[.025] p-4 sm:grid-cols-2"><div><div className="text-xs text-slate-500">{t("Location", "الموقع")}</div><div className="mt-1 text-sm">{selectedJob?.unit ?? t("Selected unit", "الوحدة المحددة")}</div></div><div><div className="text-xs text-slate-500">{t("Access note", "ملاحظة الدخول")}</div><div className="mt-1 text-sm">{t("Access instructions available in the ticket", "تعليمات الدخول متاحة في البلاغ")}</div></div></div><div className="flex flex-wrap gap-2"><Button variant={status === "IN_PROGRESS" ? "default" : "outline"} className={status === "IN_PROGRESS" ? "bg-amber-400 text-black hover:bg-amber-300" : "border-white/10 bg-transparent"} onClick={async () => { try { await updateStatus.mutateAsync({ ticketId: selectedTicketId, status: "IN_PROGRESS" }); await utils.tickets.list.invalidate(); setStatus("IN_PROGRESS"); toast.success(t("Job started", "بدأت المهمة")); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to update job", "تعذر تحديث المهمة")); } }}>{t("Start job", "بدء المهمة")}</Button><span className="rounded-xl border border-white/[.08] px-3 py-2 text-xs text-slate-500">{t("Tenant updates are sent from status changes.", "تصل تحديثات المستأجر عبر تغييرات الحالة.")}</span></div><div className="border-t border-white/[.07] pt-5"><div className="mb-3 text-sm font-semibold">{t("Completion checklist", "قائمة إتمام المهمة")}</div><label className="flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-white/15 p-4 text-sm text-slate-400 hover:border-amber-400/40"><ImagePlus size={18} className="text-amber-300"/><span>{proofUrl ? t("Proof photo attached", "تم إرفاق صورة الإثبات") : t("Upload proof photo (required)", "إرفاق صورة إثبات (مطلوب)")}</span><input type="file" className="hidden" accept="image/*" onChange={e => { const file = e.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = async () => { try { const result = await attachMedia.mutateAsync({ ticketId: selectedTicketId, fileName: file.name, contentType: file.type as "image/jpeg" | "image/png" | "image/webp" | "video/mp4" | "video/quicktime", base64Data: String(reader.result) }); setProofUrl(result.url); toast.success(t("Proof photo uploaded", "تم رفع صورة الإثبات")); } catch (error) { toast.error(error instanceof Error ? error.message : t("Upload failed", "فشل الرفع")); } }; reader.readAsDataURL(file); }}/>{proofUrl && <CheckCircle2 className="ml-auto text-emerald-300" size={17}/>}</label><Textarea value={notes} onChange={e => setNotes(e.target.value)} placeholder={t("Resolution notes (required before completing)", "ملاحظات الحل (مطلوبة قبل الإتمام)")} className="mt-3 min-h-24 border-white/10 bg-white/[.03]"/><Button disabled={!canResolve} className="mt-3 w-full bg-emerald-400 text-black hover:bg-emerald-300 disabled:cursor-not-allowed disabled:opacity-40" onClick={async () => { try { await completeTicket.mutateAsync({ ticketId: selectedTicketId, proofPhotoUrl: proofUrl, resolutionNotes: notes }); await utils.tickets.list.invalidate(); setStatus("RESOLVED"); toast.success(t("Job complete. Proof and notes added to the audit log.", "اكتملت المهمة وتمت إضافة الإثبات والملاحظات إلى سجل التدقيق.")); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to complete job", "تعذر إكمال المهمة")); } }}>{t("Mark as resolved", "تحديد كمحلول")} <CheckCircle2 size={16}/></Button>{!canResolve && <p className="mt-2 text-center text-xs text-slate-600">{t("Proof photo and resolution notes are required.", "صورة الإثبات وملاحظات الحل مطلوبة.")}</p>}</div></CardContent></Card></div></AppShell>; }

function OwnerPortal() { const { t } = useLanguage(); const liveTickets = trpc.tickets.list.useQuery(undefined, { retry: false }); const portfolioTickets = liveTickets.data?.map(ticket => ({ id: `MT-${ticket.id}`, title: ticket.title, unit: `Unit ${ticket.unitId}`, category: ticket.category, priority: ticket.priority, status: ticket.status, age: new Date(ticket.createdAt).toLocaleDateString(), description: ticket.description })) ?? []; return <AppShell role="FLAT_OWNER"><Header eyebrow="Owner view" title="Confidence in every detail." description="A read-only view of maintenance performance across your portfolio." action={<Button variant="outline" className="border-white/10 bg-transparent" onClick={() => { const header = ["Ticket", "Title", "Unit", "Category", "Priority", "Status", "Created"]; const rows = portfolioTickets.map(ticket => [ticket.id, ticket.title, ticket.unit, ticket.category, ticket.priority, ticket.status, ticket.age]); const csv = [header, ...rows].map(row => row.map(value => `"${String(value).replaceAll('"', '""')}"`).join(",")).join("\n"); const blob = new Blob([csv], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = "maintainr-portfolio-report.csv"; link.click(); URL.revokeObjectURL(url); toast.success(t("Report downloaded", "تم تنزيل التقرير")); }}>{t("Export report", "تصدير التقرير")} <FileText size={16}/></Button>}/><div className="grid gap-4 sm:grid-cols-3"><Card className="border-white/[.07] bg-[#101521]"><CardContent className="p-5"><div className="text-xs text-slate-500">{t("Portfolio health", "صحة المحفظة")}</div><div className="mt-2 text-3xl font-semibold text-emerald-300">96%</div><div className="mt-1 text-xs text-slate-500">{t("Units with no open issues", "الوحدات بدون مشاكل مفتوحة")}</div></CardContent></Card><Card className="border-white/[.07] bg-[#101521]"><CardContent className="p-5"><div className="text-xs text-slate-500">{t("Average resolution", "متوسط مدة الحل")}</div><div className="mt-2 text-3xl font-semibold">1.8d</div><div className="mt-1 text-xs text-slate-500">{t("Down 0.4d this month", "أقل بـ 0.4 يوم هذا الشهر")}</div></CardContent></Card><Card className="border-white/[.07] bg-[#101521]"><CardContent className="p-5"><div className="text-xs text-slate-500">{t("Open exposure", "التكلفة المفتوحة")}</div><div className="mt-2 text-3xl font-semibold text-amber-300">$8.4k</div><div className="mt-1 text-xs text-slate-500">{t("Estimated maintenance spend", "تقدير نفقات الصيانة")}</div></CardContent></Card></div><Card className="mt-8 border-white/[.07] bg-[#101521]"><CardHeader><CardTitle className="text-lg">{t("Recent portfolio activity", "أحدث نشاط في المحفظة")}</CardTitle></CardHeader><CardContent className="space-y-2">{portfolioTickets.map(t => <div key={t.id} className="flex flex-col justify-between gap-3 rounded-2xl border border-white/[.06] bg-white/[.02] p-4 sm:flex-row sm:items-center"><div><div className="font-medium">{t.title}</div><div className="mt-1 text-xs text-slate-500">{t.id} · Unit {t.unit} · {t.category}</div></div><div className="flex items-center gap-4"><PriorityBadge priority={t.priority}/><StatusBadge status={t.status}/></div></div>)}</CardContent></Card></AppShell>; }

function RoleRedirect() { const { user } = useAuth(); const [location, navigate] = useLocation(); useEffect(() => { if (!user || !["/", "/sign-in", "/sign-up"].includes(location)) return; const destination = user.role === "PROPERTY_MANAGER" ? "/manager" : user.role === "TENANT" ? "/tenant" : user.role === "TECHNICIAN" ? "/technician" : "/owner"; navigate(destination); }, [user, location, navigate]); return null; }

export default function App() { return <LanguageProvider><ThemeProvider defaultTheme="dark"><Toaster/><RoleRedirect/><Switch><Route path="/" component={Home}/><Route path="/sign-in"><AuthPage mode="sign-in"/></Route><Route path="/sign-up"><AuthPage mode="sign-up"/></Route><Route path="/forgot-password" component={ForgotPasswordPage}/><Route path="/reset-password" component={ResetPasswordPage}/><Route path="/apply" component={RoleApplicationPage}/><Route path="/invitation" component={InvitationPage}/><Route path="/join-unit" component={JoinUnit}/><Route path="/manager"><RoleGate role="PROPERTY_MANAGER"><ManagerPortal/></RoleGate></Route><Route path="/tenant"><RoleGate role="TENANT"><TenantPortal/></RoleGate></Route><Route path="/technician"><RoleGate role="TECHNICIAN"><TechnicianPortal/></RoleGate></Route><Route path="/owner"><RoleGate role="FLAT_OWNER"><OwnerPortal/></RoleGate></Route><Route component={Home}/></Switch></ThemeProvider></LanguageProvider>; }
